func itNl(b []byte, i int32) int32 {
	// Index of the next newline at or after i, or the blob's length.
	var k int32 = i
	for (k < port.BlobLen(b)) && (port.BlobU8(b, k) != 10) {
		k += 1
	}
	return k
}

func itSemi(b []byte, i int32, lim int32) int32 {
	// Index of the next `;` in [i, lim), or lim.
	var k int32 = i
	for (k < lim) && (port.BlobU8(b, k) != 59) {
		k += 1
	}
	return k
}

func itHexval(c int32) int32 {
	if (c >= 48) && (c <= 57) {
		return c - 48
	}
	if (c >= 97) && (c <= 102) {
		return c - 87
	}
	return -1
}

func itDec(b []byte, from int32, to int32) int32 {
	// A decimal integer, with an optional leading minus.
	var k int32 = from
	var v int32 = 0
	var neg int32 = 0
	if (k < to) && (port.BlobU8(b, k) == 45) {
		neg = 1
		k += 1
	}
	for k < to {
		v = (v * 10) + (port.BlobU8(b, k) - 48)
		k += 1
	}
	if neg == 1 {
		return 0 - v
	}
	return v
}

func itHexInto(b []byte, from int32, to int32, c *port.Cells) int32 {
	// Decode the hex pairs in b[from, to) into c (cleared first).
	var k int32 = from
	port.CellsDrop(c, 0)
	for (k + 1) < (to + 0) {
		port.CellsPush(c, (itHexval(port.BlobU8(b, k))*16)+itHexval(port.BlobU8(b, k+1)))
		k += 2
	}
	return port.CellsLen(c)
}

func itCompare(out *port.Cells, b []byte, from int32, to int32, exact int32) int32 {
	// -1 when `out` matches the hex in b[from, to): exactly, or (exact =
	// 0) as a PREFIX of it. -2 for a length problem; otherwise the
	// index of the first differing byte.
	var n int32 = (to - from) / 2
	var i int32 = 0
	if port.CellsLen(out) > n {
		return -2
	}
	if (exact == 1) && (port.CellsLen(out) != n) {
		return -2
	}
	for i < port.CellsLen(out) {
		if port.CellsAt(out, i) != ((itHexval(port.BlobU8(b, from+(i*2))) * 16) + itHexval(port.BlobU8(b, from+((i*2)+1)))) {
			return i
		}
		i += 1
	}
	return -1
}

func TestEveryRowOfTheZlibCorpus(emonT *testing.T) {
	// Fields: name ; kind ; status ; consumed ; stream-hex ; output-hex.
	var f []byte = port.TestFile("inflate/streams.txt")
	var src *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var st2 *port.Cells = port.NewCells()
	var bout *port.Buf = port.NewBuf()
	var n int32 = port.BlobLen(f)
	var k int32 = 0
	var gotb int32 = 0
	var pos int32 = 0
	var line int32 = 0
	var rows int32 = 0
	var e int32 = 0
	var s0 int32 = 0
	var s1 int32 = 0
	var s2 int32 = 0
	var s3 int32 = 0
	var s4 int32 = 0
	var kind int32 = 0
	var status int32 = 0
	var consumed int32 = 0
	var got int32 = 0
	var slen int32 = 0
	var exact int32 = 0
	for pos < n {
		line += 1
		e = itNl(f, pos)
		if (pos < e) && (port.BlobU8(f, pos) != 35) {
			rows += 1
			s0 = itSemi(f, pos, e)
			s1 = itSemi(f, s0+1, e)
			s2 = itSemi(f, s1+1, e)
			s3 = itSemi(f, s2+1, e)
			s4 = itSemi(f, s3+1, e)
			kind = port.BlobU8(f, s0+1)
			status = itDec(f, s1+1, s2)
			consumed = itDec(f, s2+1, s3)
			slen = itHexInto(f, s3+1, s4, src)
			port.CellsDrop(out, 0)
			if (kind == 122) || (kind == 90) {
				got = inflate.IzZlib(port.CellsBlob(src), 0, slen, out, st)
			} else {
				got = inflate.IzRaw(port.CellsBlob(src), 0, slen, out, st)
			}
			port.AssertEqAt(emonT, got, status, "status", line)
			if consumed >= 0 {
				port.AssertEqAt(emonT, inflate.IzConsumed(st), consumed, "consumed", line)
			}
			exact = 0
			if (kind == 90) || (kind == 82) {
				exact = 1
			}
			port.AssertEqAt(emonT, itCompare(out, f, s4+1, e, exact), -1, "output", line)
			// The Buf form (D492) is held to the Cells one on the same row: status, consumed, every byte.
			port.BufTruncate(bout, 0)
			if (kind == 122) || (kind == 90) {
				gotb = inflate.IzZlibBuf(port.CellsBlob(src), 0, slen, bout, st2)
			} else {
				gotb = inflate.IzRawBuf(port.CellsBlob(src), 0, slen, bout, st2)
			}
			port.AssertEqAt(emonT, gotb, got, "buf status", line)
			port.AssertEqAt(emonT, inflate.IzConsumed(st), inflate.IzConsumed(st2), "buf consumed", line)
			port.AssertEqAt(emonT, port.BufLen(bout), port.CellsLen(out), "buf length", line)
			k = 0
			for k < port.CellsLen(out) {
				if port.BufAt(bout, k) != port.CellsAt(out, k) {
					port.AssertEqAt(emonT, port.BufAt(bout, k), port.CellsAt(out, k), "buf byte", line)
				}
				k += 1
			}
		}
		pos = e + 1
	}
	port.AssertEq(emonT, rows, 346, "the corpus has this many rows")
}

func TestTheClassicStoredHello(emonT *testing.T) {
	// zlib.compress(b'hello', 0): header, one stored block, Adler-32.
	var out *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	port.AssertEq(emonT, inflate.IzZlib(port.HexBlob("7801 010500faff 68656c6c6f 062c0215"), 0, 16, out, st), inflate.IzOk(), "status")
	port.AssertCellsHex(emonT, out, "68656c6c6f", "hello")
	port.AssertEq(emonT, inflate.IzConsumed(st), 16, "consumed")
}

