func TestAPartialResultSurvivesDamage(emonT *testing.T) {
	// The first bytes decoded before the fault are kept.
	var out *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	port.AssertEq(emonT, inflate.IzZlib(port.HexBlob("7801 cb48cdc9c9"), 0, 7, out, st), inflate.IzTruncated(), "truncated")
	port.AssertEq(emonT, port.CellsLen(out), 4, "four bytes came out before the end")
	port.AssertEq(emonT, inflate.IzZlib(port.HexBlob("7801 cb48cdc9c90700 062c0216"), 0, 13, out, st), inflate.IzBadChecksum(), "bad checksum")
	port.AssertEq(emonT, port.CellsLen(out), 9, "and the output is kept")
}

func TestTheInputRangeIsRespected(emonT *testing.T) {
	// Only src[start, end) is read: junk before start and after end is
	// never seen, and `consumed` is an index into the whole blob.
	var out *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	port.AssertEq(emonT, inflate.IzZlib(port.HexBlob("ffff 7801 cb48cdc9c90700 062c0215 ffff"), 2, 15, out, st), inflate.IzOk(), "status")
	port.AssertEq(emonT, inflate.IzConsumed(st), 15, "consumed is absolute")
	port.AssertCellsHex(emonT, out, "68656c6c6f", "hello")
	port.AssertEq(emonT, inflate.IzZlib(port.HexBlob("7801 cb48cdc9c90700 062c0215"), 0, 12, out, st), inflate.IzTruncated(), "one byte short of the trailer")
}

